export function createStore({ capacity, concurrency }) {
  return { capacity, concurrency, nextToken: 1, jobs: [] };
}

export function step(store, command) {
  switch (command.type) {
    case 'submit':
      return submit(store, command);
    case 'claim':
      return claim(store);
    case 'complete':
      return complete(store, command);
    case 'restart':
      return restart(store);
    default:
      return { store, reply: { type: 'ignored', id: command.id } };
  }
}

function submit(store, { id, input }) {
  const existing = store.jobs.find((j) => j.id === id);
  if (existing) {
    if (existing.input !== input) {
      return { store, reply: { type: 'conflict', id } };
    }
    const reply = { type: 'duplicate', id, status: existing.status };
    if (existing.status === 'done') {
      reply.receipt = { token: existing.token, result: existing.result };
    }
    return { store, reply };
  }
  const occupied = store.jobs.filter(
    (j) => j.status === 'queued' || j.status === 'active'
  ).length;
  if (occupied >= store.capacity) {
    return { store, reply: { type: 'full', id } };
  }
  const record = { id, input, status: 'queued', token: null, result: null };
  const next = { ...store, jobs: [...store.jobs, record] };
  return { store: next, reply: { type: 'accepted', id } };
}

function claim(store) {
  const active = store.jobs.filter((j) => j.status === 'active').length;
  if (active >= store.concurrency) {
    return { store, reply: { type: 'idle' } };
  }
  const chosen = store.jobs.find((j) => j.status === 'queued');
  if (!chosen) {
    return { store, reply: { type: 'idle' } };
  }
  const token = store.nextToken;
  const jobs = store.jobs.map((j) =>
    j === chosen ? { ...j, status: 'active', token } : j
  );
  const next = { ...store, nextToken: token + 1, jobs };
  return {
    store: next,
    reply: { type: 'dispatch', id: chosen.id, input: chosen.input, token },
  };
}

function complete(store, { id, token, result }) {
  const job = store.jobs.find((j) => j.id === id);
  if (!job) {
    return { store, reply: { type: 'ignored', id } };
  }
  if (job.status === 'done') {
    if (job.token === token) {
      return {
        store,
        reply: { type: 'receipt', id, token: job.token, result: job.result },
      };
    }
    return { store, reply: { type: 'ignored', id } };
  }
  if (job.status !== 'active' || job.token !== token) {
    return { store, reply: { type: 'ignored', id } };
  }
  const jobs = store.jobs.map((j) =>
    j === job ? { ...j, status: 'done', result } : j
  );
  const next = { ...store, jobs };
  return { store: next, reply: { type: 'receipt', id, token, result } };
}

function restart(store) {
  if (!store.jobs.some((j) => j.status === 'active')) {
    return { store, reply: { type: 'restarted' } };
  }
  const jobs = store.jobs.map((j) =>
    j.status === 'active' ? { ...j, status: 'queued', token: null } : j
  );
  const next = { ...store, jobs };
  return { store: next, reply: { type: 'restarted' } };
}

