  const { id, token, result } = command;
  const index = store.jobs.findIndex((job) => job.id === id);
  if (index === -1) {
    return { store, reply: { type: 'ignored', id } };
  }

  const job = store.jobs[index];

  if (job.status === 'done') {
    if (job.token === token) {
      const reply = { type: 'receipt', id, token: job.token, result: job.result };
      return { store, reply };
    }
    return { store, reply: { type: 'ignored', id } };
  }

  if (job.status !== 'active' || job.token !== token) {
    return { store, reply: { type: 'ignored', id } };
  }

  const finished = { ...job, status: 'done', token, result };
  const jobs = store.jobs.slice();
  jobs[index] = finished;
  const nextStore = { ...store, jobs };
  return { store: nextStore, reply: { type: 'receipt', id, token, result } };
}

function restart(store) {
  const jobs = store.jobs.map((job) =>
    job.status === 'active' ? { ...job, status: 'queued', token: null } : job
