export function createStore({ capacity, concurrency }) {
  return {
    capacity,
    concurrency,
    nextToken: 1,
    jobs: []
  };
}

function findJob(store, id) {
  for (const job of store.jobs) {
    if (job.id === id) return job;
  }
  return null;
}

function cloneStore(store) {
  return {
    ...store,
    jobs: store.jobs.map((job) => ({ ...job }))
  };
}

function submit(store, { id, input }) {
  const existing = findJob(store, id);
  if (existing) {
    if (existing.input !== input) {
      return { store, reply: { type: 'conflict', id } };
    }
    const reply = { type: 'duplicate', id, status: existing.status };
    if (existing.status === 'done') {
      reply.receipt = { token: existing.token, result: existing.result };
    }
    return { store, reply };
  }

  let occupied = 0;
  for (const job of store.jobs) {
    if (job.status === 'queued' || job.status === 'active') occupied += 1;
  }
  if (occupied >= store.capacity) {
    return { store, reply: { type: 'full', id } };
  }

  const next = cloneStore(store);
  next.jobs.push({ id, input, status: 'queued', token: null, result: null });
  return { store: next, reply: { type: 'accepted', id } };
}

function claim(store) {
  let active = 0;
  let chosen = null;
  for (const job of store.jobs) {
    if (job.status === 'active') {
      active += 1;
    } else if (job.status === 'queued' && chosen === null) {
      chosen = job;
    }
  }
  if (active >= store.concurrency || chosen === null) {
    return { store, reply: { type: 'idle' } };
  }

  const next = cloneStore(store);
  const target = findJob(next, chosen.id);
  target.status = 'active';
  target.token = next.nextToken;
  next.nextToken += 1;
  return {
    store: next,
    reply: { type: 'dispatch', id: target.id, input: target.input, token: target.token }
  };
}

function complete(store, { id, token, result }) {
  const job = findJob(store, id);
  if (!job) {
    return { store, reply: { type: 'ignored', id } };
  }
  if (job.status === 'done') {
    if (job.token === token) {
      return {
        store,
        reply: { type: 'receipt', id, token: job.token, result: job.result }
      };
    }
    return { store, reply: { type: 'ignored', id } };
  }
  if (job.status !== 'active' || job.token !== token) {
    return { store, reply: { type: 'ignored', id } };
  }

  const next = cloneStore(store);
  const target = findJob(next, id);
  target.status = 'done';
  target.result = result;
  return { store: next, reply: { type: 'receipt', id, token, result } };
}

function restart(store) {
  const next = cloneStore(store);
  for (const job of next.jobs) {
    if (job.status === 'active') {
      job.status = 'queued';
      job.token = null;
    }
  }
  return { store: next, reply: { type: 'restarted' } };
}

export function step(store, command) {
  switch (command.type) {
    case 'submit':
      return submit(store, command);
    case 'claim':
      return claim(store);
    case 'complete':
      return complete(store, command);
    case 'restart':
      return restart(store);
    default:
      return { store, reply: { type: 'idle' } };
  }
}

