export function createStore({ capacity, concurrency }) {
  return { capacity, concurrency, nextToken: 1, jobs: [] };
}

export function step(store, command) {
  switch (command.type) {
    case 'submit':
      return submit(store, command);
    case 'claim':
      return claim(store);
    case 'complete':
      return complete(store, command);
    case 'restart':
      return restart(store);
    default:
      return { store, reply: { type: 'ignored', id: command.id } };
  }
}

function submit(store, command) {
  const { id, input } = command;
  const existing = store.jobs.find((job) => job.id === id);
  if (existing) {
    if (existing.input !== input) {
      return { store, reply: { type: 'conflict', id } };
    }
    const reply = { type: 'duplicate', id, status: existing.status };
    if (existing.status === 'done') {
      reply.receipt = { token: existing.token, result: existing.result };
    }
    return { store, reply };
  }
  const occupied = store.jobs.filter(
    (job) => job.status === 'queued' || job.status === 'active'
  ).length;
  if (occupied >= store.capacity) {
    return { store, reply: { type: 'full', id } };
  }
  const record = { id, input, status: 'queued', token: null, result: null };
  return {
    store: { ...store, jobs: [...store.jobs, record] },
    reply: { type: 'accepted', id },
  };
}

function claim(store) {
  const activeCount = store.jobs.filter((job) => job.status === 'active').length;
  if (activeCount >= store.concurrency) {
    return { store, reply: { type: 'idle' } };
  }
  const index = store.jobs.findIndex((job) => job.status === 'queued');
  if (index === -1) {
    return { store, reply: { type: 'idle' } };
  }
  const token = store.nextToken;
  const job = store.jobs[index];
  const jobs = store.jobs.slice();
  jobs[index] = { ...job, status: 'active', token };
  return {
    store: { ...store, nextToken: token + 1, jobs },
    reply: { type: 'dispatch', id: job.id, input: job.input, token },
  };
}

function complete(store, command) {
  const { id, token, result } = command;
  const index = store.jobs.findIndex((job) => job.id === id);
  if (index === -1) {
    return { store, reply: { type: 'ignored', id } };
  }
  const job = store.jobs[index];
  if (job.status === 'done' && job.token === token) {
    return {
      store,
      reply: { type: 'receipt', id, token: job.token, result: job.result },
    };
  }
  if (job.status !== 'active' || job.token !== token) {
    return { store, reply: { type: 'ignored', id } };
  }
  const jobs = store.jobs.slice();
  jobs[index] = { ...job, status: 'done', result };
  return {
    store: { ...store, jobs },
    reply: { type: 'receipt', id, token, result },
  };
}

function restart(store) {
  if (!store.jobs.some((job) => job.status === 'active')) {
    return { store, reply: { type: 'restarted' } };
  }
  const jobs = store.jobs.map((job) =>
    job.status === 'active' ? { ...job, status: 'queued', token: null } : job
  );
  return { store: { ...store, jobs }, reply: { type: 'restarted' } };
}

