export function createStore({ capacity, concurrency }) {
  return {
    capacity,
    concurrency,
    nextToken: 1,
    jobs: []
  };
}

export function step(store, command) {
  switch (command.type) {
    case 'submit':
      return submit(store, command);
    case 'claim':
      return claim(store);
    case 'complete':
      return complete(store, command);
    case 'restart':
      return restart(store);
    default:
      throw new Error(`Unknown command type: ${command.type}`);
  }
}

