  const existing = store.jobs.find((job) => job.id === command.id);

  if (existing) {
    if (existing.input !== command.input) {
      return {
        store,
        reply: { type: 'conflict', id: command.id }
      };
    }

    const reply = {
      type: 'duplicate',
