export function planBatch(input, capabilities) {
  if (input === null || typeof input !== "object" || Array.isArray(input)) {
    throw new TypeError("input must be a non-null, non-array object");
  }

  const { capacity, completed, jobs } = input;

  if (!Number.isInteger(capacity) || capacity < 0 || capacity > 1000000) {
    throw new TypeError("capacity must be an integer from 0 through 1000000");
  }

  if (!Array.isArray(completed)) {
    throw new TypeError("completed must be an array");
  }
  const completedSet = new Set();
  for (const id of completed) {
    if (typeof id !== "string" || id.length === 0) {
      throw new TypeError("completed entries must be nonempty strings");
    }
    if (completedSet.has(id)) {
      throw new TypeError("completed entries must be distinct");
    }
    completedSet.add(id);
  }

  if (!Array.isArray(jobs) || jobs.length > 32) {
    throw new TypeError("jobs must be an array of at most 32 entries");
  }

  const jobIds = new Set();
  for (const job of jobs) {
    if (job === null || typeof job !== "object" || Array.isArray(job)) {
      throw new TypeError("each job must be a non-null, non-array object");
    }
    if (typeof job.id !== "string" || job.id.length === 0) {
      throw new TypeError("job id must be a nonempty string");
    }
    if (jobIds.has(job.id)) {
      throw new TypeError("job ids must be distinct");
    }
    if (completedSet.has(job.id)) {
      throw new TypeError("job id must not occur in completed");
    }
    jobIds.add(job.id);
    if (!Number.isInteger(job.units) || job.units < 1 || job.units > 1000000) {
      throw new TypeError("job units must be an integer from 1 through 1000000");
    }
    if (!Array.isArray(job.after)) {
      throw new TypeError("job after must be an array");
    }
    const seen = new Set();
    for (const pred of job.after) {
      if (typeof pred !== "string" || pred.length === 0) {
        throw new TypeError("after entries must be nonempty strings");
      }
      if (seen.has(pred)) {
        throw new TypeError("after entries must be distinct");
      }
      seen.add(pred);
    }
  }

  for (const job of jobs) {
    for (const pred of job.after) {
      if (pred === job.id) {
        throw new TypeError("a job cannot name itself as a predecessor");
      }
      if (!jobIds.has(pred) && !completedSet.has(pred)) {
        throw new TypeError("predecessor must name a pending job or a completed id");
      }
    }
  }

  const selected = [];
  const remaining = [];
  let used = 0;

  for (const job of jobs) {
    let ready = true;
    for (const pred of job.after) {
      if (!completedSet.has(pred)) {
        ready = false;
        break;
      }
    }
    const entry = { id: job.id, units: job.units, after: job.after.slice() };
    if (ready && used + job.units <= capacity) {
      selected.push(entry);
      used += job.units;
    } else {
      remaining.push(entry);
    }
  }

  return {
    selected,
    remaining,
    used,
    decisions: {
      scanOrder: "fifo",
      execution: "synchronous",
      persistence: "none",
      scheduling: "none",
    },
  };
}

